
(function(){
 const FN='https://vdxkknftyssjyfbdieqa.supabase.co/functions/v1/lift-clientes',KEY='sb_publishable_ECuhXuKIb85kj9fgdEjrAw_O7uNpZsh',PASS='liftAdminCloudPasswordV1';
 let clients=[]; const $=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const pass=()=>{try{return sessionStorage.getItem(PASS)||''}catch(e){return ''}};
 async function api(payload){const r=await fetch(FN,{method:'POST',headers:{apikey:KEY,'Content-Type':'application/json'},body:JSON.stringify({...payload,password:pass()})});const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.error||'No se pudo guardar el cliente');return j}
 function injectButton(){const bar=document.querySelector('.top .bar');if(!bar||$('liftClientDirectoryBtn'))return;const b=document.createElement('button');b.id='liftClientDirectoryBtn';b.type='button';b.innerHTML='👤 Clientes';b.onclick=window.liftOpenClientDirectory;const cart=bar.querySelector('.cartDesktop');bar.insertBefore(b,cart||null)}
 async function load(){const box=$('liftClientDirList');if(box)box.innerHTML='<div class="liftClientDirEmpty">Cargando clientes…</div>';try{const j=await api({action:'crm-list'});clients=(j.clientes||[]).slice().sort((a,b)=>String(a.nombre||'').localeCompare(String(b.nombre||''),'es',{sensitivity:'base'}));render()}catch(e){if(box)box.innerHTML='<div class="liftClientDirEmpty">'+esc(e.message)+'</div>'}}
 function render(){const box=$('liftClientDirList');if(!box)return;const q=String($('liftClientDirSearch')?.value||'').trim().toLowerCase();const arr=clients.filter(c=>{const ds=(c.lift_direcciones_cliente||[]).map(d=>[d.direccion,d.ciudad,d.departamento,d.etiqueta].join(' ')).join(' ');return !q||[c.nombre,c.celular,ds].join(' ').toLowerCase().includes(q)});if(!arr.length){box.innerHTML='<div class="liftClientDirEmpty">No encontré clientes.</div>';return}box.innerHTML=arr.map(c=>{const ds=(c.lift_direcciones_cliente||[]).slice().sort((a,b)=>Number(b.predeterminada)-Number(a.predeterminada)),d=ds[0]||{};return `<button class="liftClientDirRow" type="button" onclick="liftEditClientDirectory(${Number(c.id)})"><span><span class="liftClientDirName">${esc(c.nombre||'Sin nombre')}</span><span class="liftClientDirMeta">${esc(c.celular||'Sin celular')}${d.ciudad?' · '+esc(d.ciudad):''}${ds.length?' · '+ds.length+' dirección'+(ds.length===1?'':'es'):''}</span></span><span class="liftClientDirArrow">›</span></button>`}).join('')}
 window.liftOpenClientDirectory=function(){if(!document.body.classList.contains('liftAdminUnlocked'))return;const m=$('liftClientDirectoryModal');m?.classList.add('open');m?.setAttribute('aria-hidden','false');load()};
 window.liftCloseClientDirectory=function(){const m=$('liftClientDirectoryModal');m?.classList.remove('open');m?.setAttribute('aria-hidden','true')};
 function form(c){const ds=c?.lift_direcciones_cliente||[],d=ds.slice().sort((a,b)=>Number(b.predeterminada)-Number(a.predeterminada))[0]||{};const body=$('liftClientDirContent');body.innerHTML=`<div class="liftClientDirBody"><button class="liftClientDirBack" type="button" onclick="liftClientDirectoryList()">← Clientes A → Z</button><div class="liftClientDirForm"><div class="liftClientDirField"><label>Nombre</label><input id="lcdName" value="${esc(c?.nombre||'')}"></div><div class="liftClientDirField"><label>Celular / WhatsApp</label><input id="lcdPhone" inputmode="tel" value="${esc(c?.celular||'')}"></div><div class="liftClientDirField"><label>Etiqueta de esta dirección</label><input id="lcdLabel" placeholder="Casa, trabajo…" value="${esc(d.etiqueta||'Casa')}"></div><div class="liftClientDirField"><label>Ciudad</label><input id="lcdCity" value="${esc(d.ciudad||'')}"></div><div class="liftClientDirField full"><label>Dirección</label><input id="lcdAddress" value="${esc(d.direccion||'')}"></div><div class="liftClientDirField"><label>Departamento</label><input id="lcdDept" value="${esc(d.departamento||'')}"></div><div class="liftClientDirField"><label>Barrio / sector / unidad</label><input id="lcdSector" placeholder="Opcional"></div><div class="liftClientDirField full"><label>Notas e indicaciones de entrega</label><textarea id="lcdNotes">${esc(d.notas||'')}</textarea></div>${ds.length?`<div class="liftClientDirAddresses"><b>Direcciones ya guardadas</b>${ds.map(x=>`<div class="liftClientDirAddress">${x.predeterminada?'★ ':''}${esc(x.etiqueta||'Dirección')}: ${esc(x.direccion||'')} · ${esc(x.ciudad||'')}</div>`).join('')}</div>`:''}<button class="liftClientDirSave" type="button" onclick="liftSaveClientDirectory()">Guardar cliente y dirección</button></div></div>`}
 window.liftNewClientDirectory=function(){form(null)};
 window.liftOpenNewClientDirectory=function(){if(!document.body.classList.contains('liftAdminUnlocked'))return;const m=$('liftClientDirectoryModal');m?.classList.add('open');m?.setAttribute('aria-hidden','false');form(null)};
 window.liftEditClientDirectory=function(id){form(clients.find(c=>Number(c.id)===Number(id))||null)};
 window.liftClientDirectoryList=function(){const root=$('liftClientDirContent');root.innerHTML='<div class="liftClientDirTools"><input id="liftClientDirSearch" class="liftClientDirSearch" placeholder="Buscar nombre, celular, ciudad o dirección"><button class="liftClientDirNew" type="button" onclick="liftNewClientDirectory()">+ Nuevo cliente</button></div><div class="liftClientDirBody"><div id="liftClientDirList" class="liftClientDirList"></div></div>';$('liftClientDirSearch').addEventListener('input',render);render()};
 window.liftSaveClientDirectory=async function(){const nombre=$('lcdName')?.value.trim()||'',celular=$('lcdPhone')?.value.trim()||'',direccion=$('lcdAddress')?.value.trim()||'',ciudad=$('lcdCity')?.value.trim()||'',departamento=$('lcdDept')?.value.trim()||'',etiqueta=$('lcdLabel')?.value.trim()||'Casa',sector=$('lcdSector')?.value.trim()||'',notes=$('lcdNotes')?.value.trim()||'';if(!nombre||!celular){alert('Nombre y celular son obligatorios.');return}if(!direccion||!ciudad){alert('Escribe dirección y ciudad.');return}const notas=[sector?('Sector: '+sector):'',notes].filter(Boolean).join(' · ');const btn=document.querySelector('.liftClientDirSave');if(btn){btn.disabled=true;btn.textContent='Guardando…'}try{const saved=await api({action:'save',nombre,celular,direccion,ciudad,departamento,notas,etiqueta});const verify=await api({action:'find',q:celular});const found=(verify.clientes||[]).find(c=>Number(c.id)===Number(saved.cliente_id)||String(c.celular||'').replace(/\D/g,'')===String(celular).replace(/\D/g,''));if(!found)throw new Error('Supabase respondió, pero el cliente no apareció al verificarlo.');alert('✓ Cliente guardado y verificado en Supabase');window.liftClientDirectoryList();await load();if(typeof window.liftLoadAlphabeticalClients==='function')window.liftLoadAlphabeticalClients().catch(()=>{})}catch(e){alert('No pude guardar: '+e.message)}finally{if(btn){btn.disabled=false;btn.textContent='Guardar cliente y dirección'}}};
 document.addEventListener('click',e=>{if(e.target?.id==='liftClientDirectoryModal')window.liftCloseClientDirectory()});
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('liftClientDirectoryModal')?.classList.contains('open'))window.liftCloseClientDirectory()});
 const boot=()=>{injectButton();const s=$('liftClientDirSearch');if(s)s.addEventListener('input',render)};if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(boot,150));else setTimeout(boot,150);
})();
